  const en = Object.fromEntries(Object.keys(de).map(key => [key, key]));
  const dictionaries = { en, de };
  const serverKeys = ["Teacher token required.", "Replay not found.", "Submission not found.", "Demo requires an empty waiting classroom. Reset first.", "Six demo example files are not installed.", "Six genuine example bots inserted. Start qualification to race them; no results have been fabricated.", "Type RESET to confirm clearing the classroom.", "Classroom frontend is not installed.", "Request exceeds the 64 KiB limit.", "Send a JSON request with Content-Type: application/json.", "Alias must contain 1–24 letters, digits, spaces, underscores or hyphens.", "Python source must contain valid Unicode text.", "Python code must be at most 32 KiB.", "Python source could not be parsed safely.", "A competition job is already running.", "Competition is frozen. Reset before starting a new session.", "Competition is already frozen.", "Submissions are closed or frozen.", "This alias is already claimed. Use its original claim token to update it.", "The classroom already has 60 submissions.", "Qualifications have already been started. Reset for a new competition.", "Submit at least one bot before qualifying.", "Docker sandbox unavailable; no code was executed and submissions were not frozen.", "Running qualification on three common tracks.", "Complete qualifications before starting the final.", "The final needs at least two eligible bots.", "Docker sandbox unavailable; the final was not started.", "Unable to start the competition worker.", "Worker startup failed.", "Competition interrupted. Check the Docker sandbox and retry or reset.", "Competition worker failed.", "Qualification complete.", "Final complete.", "Final complete; no bot finished, so no champion was crowned.", "Job interrupted by server restart.", "Server restarted; reset or retry the competition.", "Docker is not installed or not on PATH.", "Docker daemon is unavailable. Start Docker Desktop.", "Sandbox image is missing; build sandbox/Dockerfile first.", "Restricted Docker sandbox ready.", "Docker availability check failed or timed out.", "Docker sandbox is unavailable. Start Docker and build the bot image.", "Bot exceeded its time limit.", "Bot returned an invalid command.", "Bot exceeded its output limit.", "Bot process crashed.", "Bot disqualified.", "Classroom one-pod racing", "integer 0–100, BOOST once per race, or SHIELD", "Nearest other pod, including in the simultaneous final.", "Flush stdout after every command; no bootstrap input.", "Same three tracks and starting positions against a reference ghost; collisions disabled.", "Disqualified entries last; completed tracks descending, total turns ascending (DNF costs 700), aggregate checkpoint progress descending, case-folded alias then UUID.", "Up to five eligible snapshot bots race simultaneously without collisions. At least two needed. Only a valid finisher can become champion.", "Classroom variant, not the official CodinGame engine: width 16000, height 9000, checkpoint radius 600, pod radius 400, rotation 18 degrees/turn, friction 0.85, BOOST 650. SHIELD remains accepted and prevents thrust for three turns; it has no collision effect.", "Python syntax checked without execution; bot execution only in restricted Docker.", "invalid syntax", "expected ':'", "unexpected indent", "unterminated string literal", "Field required", "Input should be a valid string", "Input should be a valid integer", "Extra inputs are not permitted"];
  const reverseServer = new Map(serverKeys.map(key => [de[key], key]));
  // Only called for sanitized server messages/validation fields, never aliases.
  function serverText(value) {
    if (typeof value !== 'string' || !value) return value;
    if (serverKeys.includes(value)) return t(value);
    if (reverseServer.has(value)) return t(reverseServer.get(value));
    if (value.startsWith('Value error, ')) return serverText(value.slice(13));
    const syntax = /^(?:Python syntax error at line|Python-Syntaxfehler in Zeile) (\d+|None): (.*)$/.exec(value);
    if (syntax) return t('Python syntax error at line {line}: {reason}', { line: syntax[1], reason: serverText(syntax[2]) });
    return value; // Unknown diagnostics are passed through, not guessed.
  }
  class LocalizedText {
    constructor(key, values = {}) { this.key = key; this.values = values; }
    toString() { return (dictionaries[language][this.key] ?? this.key).replace(/\{(\w+)\}/g, (_, name) => String(this.values[name] ?? `{${name}}`)); }
    toJSON() { return this.toString(); }
  }
  let stored = '';
  try { stored = localStorage.getItem('pod-lab:language'); } catch { /* memory fallback */ }
  const requested = new URLSearchParams(location.search).get('lang');
  let language = ['en', 'de'].includes(requested) ? requested : ['en', 'de'].includes(stored) ? stored : 'en';
  const t = (key, values) => new LocalizedText(key, values);
  function apply() {
    document.documentElement.lang = language;
    document.querySelectorAll('[data-i18n]').forEach(node => { let value = String(t(node.dataset.i18n));
      if (node.hasAttribute('data-i18n-fragment')) {
        if (node.dataset.i18nBefore === undefined) { node.dataset.i18nBefore = node.textContent.match(/^\s*/)[0]; node.dataset.i18nAfter = node.textContent.match(/\s*$/)[0]; }
        value = node.dataset.i18nBefore + value.trim() + node.dataset.i18nAfter;
      }
      node.textContent = value; });
    for (const attribute of ['aria-label', 'placeholder', 'title']) document.querySelectorAll(`[data-i18n-${attribute}]`).forEach(node => node.setAttribute(attribute, String(t(node.getAttribute(`data-i18n-${attribute}`)))));
    document.getElementById('language-switch').value = language;
    document.querySelectorAll('nav [data-view], .wordmark').forEach(link => { const url = new URL(link.href); url.searchParams.set('lang', language); link.href = url.pathname + url.search; });
    const starter = document.querySelector('a[download="starter.py"]');
    if (starter) starter.href = `${document.body.dataset.basePath || ''}/api/starter?lang=${language}`;
    try { localStorage.setItem('pod-lab:language', language); } catch { /* language still changes in memory */ }
  }
  window.PodLocale = { t, serverText, apply, LocalizedText, get language() { return language; }, setLanguage(value) { if (!dictionaries[value]) return; language = value; apply(); } };
  apply();
